            var t = window.mySimulation.t.bind(window.mySimulation);

            if (round === 1) {
                var d1 = document.querySelector('input[name="d1"]:checked');
                var d2 = document.querySelector('input[name="d2"]:checked');
                var d3 = document.querySelector('input[name="d3"]:checked');
                if (!d1 || !d2 || !d3) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                decisions.d1 = d1.value;
                decisions.d2 = d2.value;
                decisions.d3 = d3.value;
            } else if (round === 2) {
                var d4 = document.querySelector('input[name="d4"]:checked');
                var d6 = document.querySelector('input[name="d6"]:checked');
                var d7 = document.querySelector('input[name="d7"]:checked');
                var d5checks = document.querySelectorAll('input[name="d5"]:checked');
                if (!d4 || !d6 || !d7) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                if (d5checks.length !== 3) {
                    window.mySimulation.uiManager.showNotification(t('idp_select_3'), 'warning');
                    return false;
                }
                decisions.d4 = d4.value;
                decisions.d5 = [];
                d5checks.forEach(function(c) { decisions.d5.push(c.value); });
                decisions.d6 = d6.value;
                decisions.d7 = d7.value;
            } else if (round === 3) {
                var d8 = document.querySelector('input[name="d8"]:checked');
                var d9 = document.querySelector('input[name="d9"]:checked');
                var d10 = document.querySelector('input[name="d10"]:checked');
                if (!d8 || !d9 || !d10) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                decisions.d8 = d8.value;
                decisions.d9 = d9.value;
                decisions.d10 = d10.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var results = { period: round };

            if (round === 1) {
                var sbi = d.d1 === 'b' ? 3 : 0;
                ds.sbiScore = sbi;
                results.sbiScore = sbi;

                var cGrow = 0;
                if (d.d1 === 'b') cGrow += 1;
                if (d.d2 === 'b') cGrow += 2;
                if (d.d3 === 'b') cGrow += 1;
                ds.growScore += cGrow;
                ds.growTotal += 4;
                results.carlosGrow = cGrow;

                var cCoach = (d.d1 === 'b' && d.d3 === 'b') ? 1 : 0;
                ds.coachingConversations += cCoach;
                ds.totalConversations += 1;
                ds.convCredit = ds.convCredit || {};
                ds.convCredit.carlos = cGrow / 4;
                // Stock: who owns the way forward. If Diana closes with her own answer (d3 a or c),
                // Carlos has the fix but not the habit; the effect lands in round 2.
                ds.carlosOwnership = d.d3 === 'b' ? 'carlos' : 'diana';

                if (d.d1 === 'a') ds.directiveCount++;
                else if (d.d1 === 'b') ds.coachingCount++;
                if (d.d2 === 'a') ds.directiveCount++;
                else if (d.d2 === 'b') ds.coachingCount++;
                if (d.d3 === 'a' || d.d3 === 'c') ds.directiveCount++;
                else if (d.d3 === 'b') ds.coachingCount++;

            } else if (round === 2) {
                // Delayed consequence of round 1: when the answer was Diana, Carlos waits for her again
                // at the next understaffed shift, so the Options he found never became his Will.
                if (ds.carlosOwnership === 'diana' && ds.convCredit && ds.convCredit.carlos > 0) {
                    var lost = Math.min(ds.convCredit.carlos * 4, 2);
                    ds.growScore = Math.max(0, ds.growScore - lost);
                    ds.convCredit.carlos = Math.max(0, ds.convCredit.carlos - lost / 4);
                    results.carlosWaited = true;
                }
                var yGrow = 0;
                if (d.d4 === 'b') yGrow = 4;
                else if (d.d4 === 'c') yGrow = 3;
                else yGrow = 0;
                ds.growScore += yGrow;
                ds.growTotal += 4;
                results.yolandaGrow = yGrow;

                // Shadowing (vi) is learning from others: the 20 of 70-20-10 (Lombardo & Eichinger 1996), not a stretch experience
                var idpTags = { i: '10', ii: '70', iii: '20', iv: '70', v: '20', vi: '20' };
                var s70 = 0;
                var s20 = 0;
                var s10 = 0;
                if (d.d5 && d.d5.length) {
                    d.d5.forEach(function(opt) {
                        if (idpTags[opt] === '70') s70++;
                        else if (idpTags[opt] === '20') s20++;
                        else s10++;
                    });
                }
                var idpQ = s70 >= 2 ? 100 : (s70 === 1 ? 60 : 30);
                ds.idpScore = idpQ;
                results.idpScore = idpQ;
                results.idp70 = s70;
                results.idp20 = s20;
                results.idp10 = s10;

                var yCoach = (d.d4 === 'b' || d.d4 === 'c') ? 1 : 0;
                ds.coachingConversations += yCoach;
                ds.totalConversations += 1;

                var rGrow = 0;
                if (d.d6 === 'b') rGrow += 2;
                if (d.d7 === 'b') rGrow += 2;
                ds.growScore += rGrow;
                ds.growTotal += 4;
                results.robertoGrow = rGrow;

                // An opening on the figure of the offer makes the conversation transactional: the career
                // question that follows lands only half (Roberto answers with the number).
                var retS = 0;
                if (d.d6 === 'b') retS += 50;
                if (d.d7 === 'b') retS += (d.d6 === 'b' ? 50 : 25);
                else if (d.d7 === 'a') retS += 20;
                ds.retentionScore = retS;
                results.retentionScore = retS;

                var rCoach = (d.d6 === 'b') ? 1 : 0;
                ds.coachingConversations += rCoach;
                ds.totalConversations += 1;

                ds.robertoEngagement = d.d6 === 'b' ? 'open' : (d.d6 === 'a' ? 'transactional' : 'guarded');

                if (d.d4 === 'a') ds.directiveCount++;
                else ds.coachingCount++;
                if (d.d6 === 'a') ds.directiveCount++;
                else if (d.d6 === 'b') ds.coachingCount++;
                else ds.directiveCount += 0.5;
                if (d.d7 === 'b') ds.coachingCount++;
                else ds.directiveCount++;

            } else if (round === 3) {
                // Marcos: the respectful reframe holds the coaching relationship; turning his insight into
                // his own stretch assignment completes it. Mediation is the fifth conversation.
                var mCoach = d.d8 === 'b' ? (d.d9 === 'b' ? 1 : 0.5) : (d.d9 === 'b' ? 0.25 : 0);
                ds.coachingConversations += mCoach;
                ds.totalConversations += 1;
                var medCoach = d.d10 === 'b' ? 1 : (d.d10 === 'c' ? 0.5 : 0);
                ds.coachingConversations += medCoach;
                ds.totalConversations += 1;
                // The second offer (event): a career conversation holds Roberto; a transactional or
                // need-based one does not survive a better offer that needs no relocation.
                if (ds.randomEvents && ds.randomEvents.r3_roberto_offer && ds.robertoEngagement !== 'open' && ds.retentionScore > 0) {
                    ds.retentionScore = 0;
                    results.robertoLeft = true;
                }
                results.retentionScore = ds.retentionScore;

                if (d.d8 === 'a') ds.directiveCount++;
                else if (d.d8 === 'b') ds.coachingCount++;

                if (d.d9 === 'b') ds.coachingCount++;
                else if (d.d9 === 'a') ds.directiveCount += 0.5;

                if (d.d10 === 'a') ds.directiveCount++;
                else if (d.d10 === 'b') ds.coachingCount++;
                else ds.coachingCount += 0.5;
            }

            var growPct = ds.growTotal > 0 ? Math.round(ds.growScore / ds.growTotal * 100) : 0;
            var totalStyle = ds.coachingCount + ds.directiveCount;
            var stylePct = totalStyle > 0 ? Math.round(ds.coachingCount / totalStyle * 100) : 50;
            var conPct = ds.totalConversations > 0 ? Math.round(ds.coachingConversations / ds.totalConversations * 100) : 0;

            ds.growHistory.push(growPct);
            ds.consistencyHistory.push(conPct);
            ds.overallHistory.push(stylePct);

            results.growPct = growPct;
            results.consistencyPct = conPct;
            results.stylePct = stylePct;
            results.sbiDisplay = ds.sbiScore >= 0 ? ds.sbiScore + '/3' : '--';
            results.idpDisplay = ds.idpScore >= 0 ? ds.idpScore + '%' : '--';
            results.retentionDisplay = ds.retentionScore >= 0 ? ds.retentionScore + '%' : '--';

            // Defensive: expose the composite score on domainState for any framework/report
            // layer that reads it directly. Uses the SAME weights as getPerformanceSummary.
            results.sbiPct = ds.sbiScore >= 3 ? 100 : 0;
            results.idpPct = ds.idpScore >= 0 ? ds.idpScore : 0;
            results.retPct = ds.retentionScore >= 0 ? ds.retentionScore : 0;
            ds.totalScore = this._composite(results);
            results.totalScore = ds.totalScore;

            // Platform score: same value as ds.totalScore above, exposed where the platform reads it
            var overallScore = Math.max(0, Math.min(100, ds.totalScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || 3;
            if (round < maxP) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: round + 1, domainState: ds });
                }, 500);
            }

            return results;
        }

        _composite(r) {
            // One function for the gradebook score and the debrief (weights from concept §7)
            var w = (r.growPct || 0) * 30 + (r.sbiPct || 0) * 20 + (r.idpPct || 0) * 20 + (r.consistencyPct || 0) * 20 + (r.retPct || 0) * 10;
            return Math.max(0, Math.min(100, Math.round(w / 100)));
        }

        _tier(score) {
            // Bands derived from the sweep: P6 = 100; random-play p90 = 77; one core coaching error lands below 90
            if (score >= 90) return 'exemplary';
            if (score >= 70) return 'developing';
            if (score >= 50) return 'transition';
            return 'apprentice';
        }

        setupUI(uiManager) {
            // After an undo the engine rewinds the period but nothing re-renders the adapter's
            // panel: the student saw the next round's questions under the replayed round (G-F).
            var self = this;
            try {
                var bus = window.mySimulation && window.mySimulation.eventBus;
                if (bus && !this._undoBound) {
                    this._undoBound = true;
                    bus.on('period:undone', function(st) { self._updateBriefing((window.mySimulation && window.mySimulation.state) || st); });
                }
            } catch (e) { /* no bus: nothing to bind */ }
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('growDisplay', 'results.growPct', function(v) { return v + '%'; });
            uiManager.bind('sbiDisplay', 'results.sbiDisplay');
            uiManager.bind('idpDisplay', 'results.idpDisplay');
            uiManager.bind('consistencyDisplay', 'results.consistencyPct', function(v) { return v + '%'; });
            uiManager.bind('retentionDisplay', 'results.retentionDisplay');
        }

        _tx(k) { try { return window.mySimulation ? window.mySimulation.t(k) : k; } catch (e) { return k; } }

        getChartConfig() {
            return {
                coachingChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._tx('chart_grow'),
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: this._tx('chart_style'),
                            data: [],
                            borderColor: '#2980b9',
                            backgroundColor: 'rgba(41,128,185,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: this._tx('chart_consistency'),
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
