        getChartData(state) {
            var labels = state.domainState.growHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                coachingChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.growHistory },
                        { data: state.domainState.overallHistory },
                        { data: state.domainState.consistencyHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            if (!history.length) return { totalPeriods: 0 };
            var last = history[history.length - 1];
            var r = last.results || {};

            var growPct = r.growPct || 0;
            var sbiPct = r.sbiPct != null ? r.sbiPct : ((r.sbiDisplay === '3/3') ? 100 : 0);
            var idpPct = r.idpPct != null ? r.idpPct : (r.idpDisplay && r.idpDisplay !== '--' ? parseInt(r.idpDisplay) : 0);
            var conPct = r.consistencyPct || 0;
            var retPct = r.retPct != null ? r.retPct : (r.retentionDisplay && r.retentionDisplay !== '--' ? parseInt(r.retentionDisplay) : 0);

            var weighted = this._composite({ growPct: growPct, sbiPct: sbiPct, idpPct: idpPct, consistencyPct: conPct, retPct: retPct });
            var tier = this._tier(weighted);
            var performance = t('tier_' + tier);

            // Run-specific debrief: each mistake is read from the decisions actually made (B12, S4)
            var dec = {}, flags = {};
            history.forEach(function(h) {
                var hd = h.decisions || {};
                Object.keys(hd).forEach(function(k) { dec[k] = hd[k]; });
                var hr = h.results || {};
                if (hr.robertoLeft) flags.robertoLeft = true;
            });
            var s70 = 0, tags = { i: '10', ii: '70', iii: '20', iv: '70', v: '20', vi: '20' };
            (dec.d5 || []).forEach(function(o) { if (tags[o] === '70') s70++; });
            var found = [];   // [impact, key] - impact orders the turning point
            if (dec.d1 === 'c') found.push([25, 'dbf_d1c']);
            else if (dec.d1 === 'a') found.push([25, 'dbf_d1a']);
            if (dec.d3 === 'a' || dec.d3 === 'c') found.push([11, 'dbf_d3']);
            if (dec.d2 === 'a' || dec.d2 === 'c') found.push([8, 'dbf_d2']);
            if (dec.d4 === 'a') found.push([14, 'dbf_d4a']);
            if (dec.d5 && s70 < 2) found.push([s70 === 0 ? 14 : 8, 'dbf_idp']);
            if (dec.d6 === 'a') found.push([19, 'dbf_d6a']);
            else if (dec.d6 === 'c') found.push([19, 'dbf_d6c']);
            if (dec.d7 === 'a') found.push([6, 'dbf_d7a']);
            else if (dec.d7 === 'c') found.push([7, 'dbf_d7c']);
            if (flags.robertoLeft) found.push([10, 'dbf_roberto_left']);
            if (dec.d8 === 'a') found.push([5, 'dbf_d8a']);
            else if (dec.d8 === 'c') found.push([5, 'dbf_d8c']);
            if (dec.d9 === 'a' || dec.d9 === 'c') found.push([2, 'dbf_d9']);
            if (dec.d10 === 'a') found.push([4, 'dbf_d10a']);
            else if (dec.d10 === 'c') found.push([2, 'dbf_d10c']);
            var ranked = found.slice().sort(function(x, y) { return y[0] - x[0]; });
            var turningKey = ranked.length ? ranked[0][1] : null;
            var insights = ranked.slice(1, 5).map(function(x) { return t(x[1]); });
            if (!turningKey) insights.push(t('insight_excellent'));

            return {
                totalScore: weighted,
                overallScore: weighted,
                score: weighted,
                totalPeriods: history.length,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: performance,
                turningPointKey: turningKey,
                turningPoint: turningKey ? t(turningKey) : '',
                scoreBreakdown: { grow: growPct, sbi: sbiPct, idp: idpPct, consistency: conPct, retention: retPct },
                insights: insights,
                questions: [t('dq1'), t('dq2')]
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            var b = summary.scoreBreakdown || {};
            function row(label, val) {
                return '<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid #eee;">' +
                       '<span style="color:#555;">' + label + '</span><strong>' + val + '</strong></div>';
            }
            var rows = row(t('grow_label'), (b.grow != null ? b.grow : 0) + '%') +
                       row(t('sbi_label'), (b.sbi != null ? b.sbi : 0) + '%') +
                       row(t('idp_label'), (b.idp != null ? b.idp : 0) + '%') +
                       row(t('consistency_label'), (b.consistency != null ? b.consistency : 0) + '%') +
                       row(t('retention_label'), (b.retention != null ? b.retention : 0) + '%');
            var insights = (summary.insights || []).map(function(i) { return '<li style="margin-bottom:6px;">' + i + '</li>'; }).join('');
            var turning = summary.turningPointKey ? '<div style="max-width:480px;margin:0 auto 14px;text-align:left;border-left:4px solid #c0392b;padding:6px 10px;background:#fdf2f0;"><h5 style="margin:0 0 6px;">' + t('turning_label') + '</h5><div>' + t(summary.turningPointKey) + '</div></div>' : '';
            var qs = (summary.questions && summary.questions.length) ? '<div style="max-width:480px;margin:14px auto 0;text-align:left;"><h5 style="margin-bottom:8px;">' + t('questions_label') + '</h5><ol style="padding-left:20px;margin:0;"><li style="margin-bottom:6px;">' + t('dq1') + '</li><li>' + t('dq2') + '</li></ol></div>' : '';
            return '<div style="text-align:center;padding:10px;">' +
                   '<div style="font-size:0.8rem;text-transform:uppercase;letter-spacing:1px;color:#888;">' + t('final_score_label') + '</div>' +
                   '<div style="font-size:3rem;font-weight:700;color:#2c3e50;line-height:1.1;">' + (summary.totalScore != null ? summary.totalScore : 0) + '<span style="font-size:1.2rem;color:#888;">/100</span></div>' +
                   '<div style="font-size:1.15rem;font-weight:600;color:#1e7e45;margin-bottom:18px;">' + (summary.performanceLabel || (summary.performanceKey ? t(summary.performanceKey) : '')) + '</div>' +
                   '<div style="max-width:420px;margin:0 auto 18px;text-align:left;">' + rows + '</div>' + turning +
                   (insights ? '<div style="max-width:480px;margin:0 auto;text-align:left;"><h5 style="margin-bottom:8px;">' + t('takeaways_label') + '</h5><ul style="padding-left:20px;margin:0;">' + insights + '</ul></div>' : '') + qs +
                   '</div>';
        }

        getHint(state, results) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (state.currentPeriod === 1) {
                if (results.sbiScore < 3) return t('hint_sbi');
                if (results.carlosGrow < 3) return t('hint_grow_carlos');
            }
            if (state.currentPeriod === 2) {
                if (results.idpScore < 60) return t('hint_idp');
                if (results.retentionScore < 50) return t('hint_retention');
            }
            if (state.currentPeriod === 3) {
                if (results.stylePct < 50) return t('hint_directive');
            }
            return null;
        }

